    def longestBalanced(self, s: str) -> int:
        n = len(s)
        ans = 1
        for i in range(n):
            cnt = [0, 0, 0]
            for j in range(i, n):
                cnt[ord(s[j]) - 97] += 1
                a, b, c = cnt
                if (a == b == c) or (a and b and a == b and c == 0) or \
                   (a and c and a == c and b == 0) or (b and c and b == c and a == 0):
                    ans = max(ans, j - i + 1)
        return ans

