    int longestBalanced(string s) {
        int n = s.size(), ans = 1;
        for (int i = 0; i < n; i++) {
            int cnt[3] = {0,0,0};
            for (int j = i; j < n; j++) {
                cnt[s[j]-'a']++;
                int a = cnt[0], b = cnt[1], c = cnt[2];
                bool bal = (a==b && b==c) || (a&&b&&a==b&&!c) || (a&&c&&a==c&&!b) || (b&&c&&b==c&&!a);
                if (bal) ans = max(ans, j - i + 1);
            }
        }
        return ans;
    }
};

