class Solution:
    def longestBalanced(self, s: str) -> int:
        n = len(s)
        ans = 1
        seen = {(0, 0): -1}
        a = b = c = 0
        for i, ch in enumerate(s):
            if ch == 'a': a += 1
            elif ch == 'b': b += 1
            else: c += 1
            k = (a - b, b - c)
            if k in seen: ans = max(ans, i - seen[k])
            else: seen[k] = i
        for x, y, z in (('a','b','c'), ('a','c','b'), ('b','c','a')):
            last = {0: -1}
            dx = dy = 0
            for i, ch in enumerate(s):
                o = ord(ch) - 97
                if o == z:
                    last = {0: i}
                    dx = dy = 0
                    continue
                if o == x: dx += 1
                else: dy += 1
                k = dx - dy
                if k in last: ans = max(ans, i - last[k])
                else: last[k] = i
        return ans

