class Solution {
public:
    int longestBalanced(string s) {
        int n = s.size(), ans = 1;
        map<pair<long long,long long>, int> seen;
        long long a = 0, b = 0, c = 0;
        seen[{0, 0}] = -1;
        for (int i = 0; i < n; i++) {
            if (s[i]=='a') a++; else if (s[i]=='b') b++; else c++;
            auto k = make_pair(a-b, b-c);
            auto it = seen.find(k);
            if (it != seen.end()) ans = max(ans, i - it->second);
            else seen[k] = i;
        }
        int dirs[3][3] = {{0,1,2},{0,2,1},{1,2,0}};
        for (auto& d : dirs) {
            int x = d[0], y = d[1], z = d[2];
            map<int,int> last; last[0] = -1;
            long long dx = 0, dy = 0;
            for (int i = 0; i < n; i++) {
                int ch = s[i] - 'a';
                if (ch == z) { last.clear(); last[0] = i; dx = dy = 0; continue; }
                if (ch == x) dx++; else dy++;
                auto it = last.find(dx - dy);
                if (it != last.end()) ans = max(ans, i - it->second);
                else last[dx - dy] = i;
            }
        }
        return ans;
    }
};

