class Solution {
    public int longestBalanced(String s) {
        int n = s.length(), ans = 1;
        Map<Long, Integer> seen = new HashMap<>();
        long a = 0, b = 0, c = 0;
        seen.put(0L, -1);
        for (int i = 0; i < n; i++) {
            if (s.charAt(i)=='a') a++; else if (s.charAt(i)=='b') b++; else c++;
            long k = (a - b) * 400001L + (b - c);
            Integer p = seen.get(k);
            if (p != null) ans = Math.max(ans, i - p);
            else seen.put(k, i);
        }
        int[][] dirs = {{0,1,2},{0,2,1},{1,2,0}};
        for (int[] d : dirs) {
            int x = d[0], y = d[1], z = d[2];
            Map<Integer, Integer> last = new HashMap<>();
            last.put(0, -1);
            long dx = 0, dy = 0;
            for (int i = 0; i < n; i++) {
                int ch = s.charAt(i) - 'a';
                if (ch == z) { last.clear(); last.put(0, i); dx = dy = 0; continue; }
                if (ch == x) dx++; else dy++;
                int k = (int)(dx - dy);
                Integer p = last.get(k);
                if (p != null) ans = Math.max(ans, i - p);
                else last.put(k, i);
            }
        }
        return ans;
    }
}

